import{d as c,C as t,o as u,c as g,j as a,a as n,E as i,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第十章","description":"从抱一、致柔与玄览的六问，读到生养而不占有的玄德。","frontmatter":{"title":"道德经第十章","description":"从抱一、致柔与玄览的六问，读到生养而不占有的玄德。","category":"guide","aliases":["道德经第十章","老子第十章","dao de jing chapter 10"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-10.md","filePath":"daoism/dao-de-jing/chapter-10.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-10.md"},_=c({...p,setup(b){const s=[{id:"holding-unity-and-reaching-softness",label:"载营魄抱一，能无离乎",showLabel:!0,sentences:[["载",{text:"营魄",glossary:"yingpo"},{text:"抱一",glossary:"baoyi"},"，能无离乎？"],["专气致柔，能婴儿乎？"]],note:["【白话】安处身心而持守其本真，能不相离吗？任气自然而达到柔和，能像婴儿那样吗？","【王弼注择要】「载，犹处也。」「一，人之真也。」又释「专，任也」，以「任自然之气」说明致柔。注着眼于安处、清神与无所欲的柔和。","【读法】营魄的解释历来有分歧，本页以王弼对人之居处、抱一清神的说明作白话，不把它定成某种现代生理结构。婴儿取柔和少欲之象，句子没有提供强行调息或闭气的方法。"]},{id:"clearing-the-inner-vision",label:"涤除玄览，能无疵乎",showLabel:!0,sentences:[["涤除",{text:"玄览",glossary:"xuanlan"},"，能无疵乎？"]],note:["【白话】洗除遮蔽，使幽深的观照保持清明，能没有瑕疵吗？","【王弼注择要】「言能涤除邪饰」，又说「能不以物介其明，疵之其神乎」。注从除去偏饰、不使事物遮隔清明来解释这一问。","【读法】涤除所针对的是观照中的遮蔽，不是取消一切所见之物。这里可以联系认识的偏差来思考，但不能把玄览直接宣称为不需证据的特殊能力。"]},{id:"governing-without-cunning",label:"爱民治国，能无知乎",showLabel:!0,sentences:[["爱民治国，能无",{text:"知",glossary:"zhi"},"乎？"]],note:["【白话】爱护百姓、治理国家，能够不依靠机巧权术吗？","【王弼注择要】「任术以求成，运数以求匿者，智也。」注将所去的智落在术数机巧，不是在要求治理者对民情、事务全然无知。","【读法】这一问把前面的自处与观照转到治理。无知依王弼注取不任智巧义，与第三章可以参读；不能据此否定治理所需的信息、能力与公共讨论。"]},{id:"responding-without-forcing",label:"天门开阖，能为雌乎",showLabel:!0,sentences:[[{text:"天门",glossary:"tianmen"},"开阖，能为",{text:"雌",glossary:"ci"},"乎？"],["明白四达，能",{text:"无为",glossary:"wuwei"},"乎？"]],note:["【白话】面对天下治乱变化的开合，能够处在回应、承接的一面吗？即使明白通达四方，能够仍不强作妄为吗？","【王弼注择要】「开阖，治乱之际也。」「雌应而不昌，因而不为。」关于明白四达，注又问「能无以为乎」，强调通达之后仍不以己意强作。","【读法】本段循王弼以天下之所由、治乱之际解释天门，不径直套成身体孔窍。雌在这里取回应、承接之象，不是对女性应当被动的规定；明白也不自动授予控制一切的资格。"]},{id:"nurturing-without-owning",label:"生而不有，为而不恃",showLabel:!0,sentences:[["生之",{text:"畜",glossary:"xu"},"之，生而不有，"],["为而不",{text:"恃",glossary:"shi"},"，",{text:"长",glossary:"zhang"},"而不",{text:"宰",glossary:"zai"},"，"],["是谓",{text:"玄德",glossary:"xuande"},"。"]],note:["【白话】使它们生长、养育它们，生养而不据为己有，有所作为而不自恃其功，长养而不加以主宰，这称为幽深而不自显的德。","【王弼注择要】「不塞其原」，「不禁其性」。注又说「凡言玄德，皆有德而不知其主，出乎幽冥」。成就万物，却不以自己为显见的功主，是本章的收束。","【读法】前面六问在这里落成生养的方式。不有、不恃、不宰没有撤去支持与责任，而是不把被生养者当作自己的附属。长读 zhǎng，畜读 xù。"]}],o=[{id:"yingpo",term:"营魄",sense:1},{id:"baoyi",term:"抱一",sense:1},{id:"xuanlan",term:"玄览",sense:1},{id:"zhi",term:"知",sense:1,pinyin:"zhì",context:"与智相通，王弼本章明确针对术数机巧；不作反对一切知识解。"},{id:"tianmen",term:"天门",sense:1},{id:"ci",term:"雌",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"xu",term:"畜",sense:1,pinyin:"xù"},{id:"shi",term:"恃",sense:1},{id:"zhang",term:"长",sense:1,pinyin:"zhǎng"},{id:"zai",term:"宰",sense:1},{id:"xuande",term:"玄德",sense:1}];return(x,e)=>{const r=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十章",tabindex:"-1"},[n("道德经第十章 "),a("a",{class:"header-anchor",href:"#道德经第十章","aria-label":'Permalink to "道德经第十章"'},"​")],-1)),i(r,{title:"六次追问，归于生养而不占有",summary:"本章以六个「能……乎」不断自问：从抱一、致柔、观照，走到爱民、应变与通达。篇末再用生养而不占有、长养而不主宰，说明这些问题最终要落成怎样的德。",points:[{label:"先读",text:"先数清六问，辨认它们各自在问什么。"},{label:"再辨",text:"从自处到治理，少造作的线索如何贯通？"},{label:"后想",text:"有支持与成就，为何仍要不有、不宰？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[n("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),i(l,{sections:s,glossary:o,tone:"ink",density:"comfortable","aria-label":"《道德经》第十章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[n("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),i(d,{lines:[{text:"载营魄抱一，能无离乎？",tone:"自处",guide:"第一问先把持守本真立起来，后面才谈柔和与清明。能乎的问法邀请持续检查，不是一句已经完成的自我宣告。"},{text:"爱民治国，能无知乎？",tone:"转治",guide:"自处与观照不只服务个人安定，也被带入如何对待他人的问题。依王弼注，去的是机巧权术，不是必需的学习与判断。"},{text:"明白四达，能无为乎？",tone:"自限",guide:"即使自认为通达，仍要问能否少些强作。能力越大，越需要检查自己是否将所知变成了包办一切的理由。"},{text:"生而不有，为而不恃，长而不宰。",tone:"成德",guide:"六问没有收在自我完美，而是落到如何生养万物。不占有、不自恃、不主宰，使支持别人的行动保留对方自己的生长。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[n("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),i(h,{items:o}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-六问为什么把身心与治国写在一章" tabindex="-1">象：六问为什么把身心与治国写在一章？ <a class="header-anchor" href="#象-六问为什么把身心与治国写在一章" aria-label="Permalink to &quot;象：六问为什么把身心与治国写在一章？&quot;">​</a></h3><p>抱一、致柔、涤除玄览偏向自处，爱民、天门与四达则转向治理和应变。它们各有对象，不能合成一种单一技巧；但都追问人是否能减少偏饰、执取与强作。结尾以生养而不占有，把自处与待物的方向接起来。</p><h3 id="理-明白之后-为什么还要问能否无为" tabindex="-1">理：明白之后，为什么还要问能否无为？ <a class="header-anchor" href="#理-明白之后-为什么还要问能否无为" aria-label="Permalink to &quot;理：明白之后，为什么还要问能否无为？&quot;">​</a></h3><p>以为看清了，就急于替万物决定一切，仍可能回到智巧造作。王弼对雌的解释侧重回应、因循，对玄德则侧重不堵塞根源、不禁止本性。通达的意义因而不只在能做多少，也在能否辨明哪些行动会遮蔽对方自身的作用。</p><h3 id="用-生养而不占有如何与责任并行" tabindex="-1">用：生养而不占有如何与责任并行？ <a class="header-anchor" href="#用-生养而不占有如何与责任并行" aria-label="Permalink to &quot;用：生养而不占有如何与责任并行？&quot;">​</a></h3><p>教育、指导与协作都需要真实投入：提供条件、辨认风险、承担约定责任。同时，可以避免把帮助变成对他人的长期支配。是否应当介入，要看具体能力与处境；「不宰」既不是放任危险，也不要求帮助者完全没有自己的边界。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>把六问当作检查次序的启发。</strong> 行动前先检查自己的执念、状态与偏见，再看是否掌握实际情况、能否适当回应。这里借用的是自问的形式，不是把古代概念改造成一套已经验证的身心疗法。</p><p><strong>让被帮助者逐步取得主动。</strong> 指导新人时，可以把决定依据讲清楚、让对方试做，并根据风险逐步交还判断。成果出现后承认对方的能力与劳动，比反复提醒「都是我教的」更接近不有、不恃的启发。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：六问中，哪一问最贴近我当前的困难？一次帮助里，我提供了哪些条件，又有没有把对方的成长当作自己的所有物？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文保留本站「明白四达，能无为乎」；HFL 电子录文此处作「能无知乎」，但王弼注以「能无以为乎」申说。本页据注解释不强作，并将文字差异保留在此。</li><li>本页沿用「生之畜之」。所据 HFL 经注连排录文在此接「生之不塞其原也，畜之不禁其性也」，可见生、畜及其注语，未独立连写成本站这一整句，不称两处录文完全一致。</li><li>「营魄」「玄览」「天门」均有其他解释传统；本页循王弼取径。「雌应而不昌」保留录文的昌，本页按倡发之意理解。</li><li>本章采用古注的义理说明，不将专气致柔写成具体呼吸训练，也不将雌性意象写成社会角色规范。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，006a–007a</a>。</p>',15))])}}});export{y as __pageData,_ as default};
